import React, { useState } from 'react';
import axios from 'axios';

const AddComment = ({ postId, comment = null, onCommentAdded }) => {
    const [content, setContent] = useState(comment ? comment.content : "");
    const [error, setError] = useState("");

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");

        const token = localStorage.getItem('authToken');
        const userId = localStorage.getItem('userId');

        try {
            if (comment) {
                // Update existing comment
                await axios.put(`http://localhost:6543/api/comments/update/${comment.id}`, 
                    { userId, newContent: content },
                    { headers: { Authorization: `Bearer ${token}` } }
                );
            } else {
                // Create new comment
                await axios.post(`http://localhost:6543/api/comments/add`, 
                    { postId, userId, content },
                    { headers: { Authorization: `Bearer ${token}` } }
                );
            }

            setContent("");
            onCommentAdded(); // Refresh comment list
        } catch (err) {
            console.error("Failed to submit comment:", err);
            setError(err.response?.data?.message || "An error occurred.");
        }
    };

    return (
        <form onSubmit={handleSubmit}>
            <textarea 
                value={content} 
                onChange={(e) => setContent(e.target.value)}
                placeholder="Write a comment..."
                required
            />
            <button type="submit">{comment ? "Update" : "Post"}</button>
            {error && <p style={{ color: 'red' }}>{error}</p>}
        </form>
    );
};

export default AddComment;
